// At rank r, the eligible positions are the unassigned positions in
// [r - 2, n]. There are three of them until fewer than three ranks remain.
// When the maximum is fixed, remove it and bring in the next position.
//
// A state describes the feasible relative orders of the rightmost seven
// unassigned positions, stored in decreasing position order. The table
// separates those orders with a comparison and removes any forced maxima,
// including any that become forced after the window shifts.
//
// The comparison policies were computed over these states, once for uniform
// legal orders and once for worst-case cost. Use an average-cost choice only
// when its two branches still fit the worst-case budget. The large-size bound
// repeats every 15 ranks with 25 extra comparisons.
// Generated by enumerating the feasible descending orders of each window.
// Each comparison leads to another state and a sequence of forced maxima.
constexpr int windowSize = 7;
constexpr int periodicFrom = 35;
constexpr int period = 15;
constexpr int phases = periodicFrom + period;

struct Branch { uint16_t state, removed; };
struct Comparison { uint8_t left, right; Branch branch[2]; };
struct Rule {
    int8_t worstOffset;
    uint8_t carryOrder;
    uint16_t average, minimax, monotone;
    uint8_t averageExtra, monotoneExtra;
};

